import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    N = int(next(iterator))

    estoque = [0] * (N + 1)
    for i in range(1, N + 1):
        estoque[i] = int(next(iterator))

    P = int(next(iterator))
    vendas = 0

    for _ in range(P):
        pedido = int(next(iterator))
        if estoque[pedido] > 0:
            estoque[pedido] -= 1
            vendas += 1

    print(vendas)

if __name__ == '__main__':
    main()
